<template>
	<view class="container">
		<!-- 自定义导航栏占位 -->
		<view class="nav-bar" :style="{ paddingTop: navBarHeight + 'px' }">
			<view class="nav-content">
				<text class="nav-title">{{ navTitle }}</text>
			</view>
		</view>

		<!-- 搜索栏 -->
		<view class="search-bar" :style="{ top: (navBarHeight + 44) + 'px' }">
			<input class="search-input" type="text" v-model="searchKeyword" placeholder="输入地点名称..."
				placeholder-class="placeholder" @confirm="onManualSearch" />
			<button class="search-btn" @click="onManualSearch">搜索</button>
		</view>

		<!-- 地图 -->
		<map id="addressMap" class="map-view" :latitude="mapLatitude" :longitude="mapLongitude" :markers="markers"
			:scale="mapScale" @tap="onMapTap"></map>

		<!-- 定位按钮（可选辅助） -->
		<view class="locate-btn" @click="onLocateClick">
			<text class="locate-icon">{{ locating ? '...' : '⌖' }}</text>
		</view>

		<!-- 常用地点快捷选择 -->
		<view class="quick-locations" v-if="showQuickLocations">
			<text class="quick-title">常用地点</text>
			<scroll-view class="quick-scroll" scroll-x>
				<view class="quick-list">
					<view class="quick-item" v-for="item in quickLocations" :key="item.name" @click="selectQuickLocation(item)">
						<text>{{ item.name }}</text>
					</view>
				</view>
			</scroll-view>
		</view>

		<!-- 底部确认栏 -->
		<view class="bottom-bar">
			<view class="selected-info" v-if="selectedAddress">
				<text class="selected-name">{{ selectedAddress.name }}</text>
				<text class="selected-addr">{{ selectedAddress.address || '' }}</text>
			</view>
			<view class="selected-info" v-else>
				<text class="selected-tip">点击地图选择位置</text>
			</view>
			<button class="confirm-btn" @click="confirmAddress" :disabled="!selectedAddress">确认地址</button>
		</view>
	</view>
</template>

<script setup>
import { onLoad } from '@dcloudio/uni-app'
import { ref } from 'vue'

const searchKeyword = ref('')
const mapLatitude = ref(29.413)
const mapLongitude = ref(106.5655)
const mapScale = ref(17)
const selectedAddress = ref(null)
const markers = ref([])
const addressType = ref('destination')
const navTitle = ref('选择收件地址')
const navBarHeight = ref(0)
const locating = ref(false)
const showQuickLocations = ref(true)

// 常用地点（学校附近）
const quickLocations = [
	{ name: '菜鸟驿站', address: '菜鸟驿站取件点', latitude: 29.413, longitude: 106.5655 },
	{ name: '顺丰取件点', address: '顺丰快递取件点', latitude: 29.414, longitude: 106.566 },
	{ name: '京东取件点', address: '京东快递取件点', latitude: 29.412, longitude: 106.564 },
	{ name: '1号宿舍楼', address: '1号宿舍楼', latitude: 29.415, longitude: 106.565 },
	{ name: '2号宿舍楼', address: '2号宿舍楼', latitude: 29.414, longitude: 106.564 },
	{ name: '3号宿舍楼', address: '3号宿舍楼', latitude: 29.416, longitude: 106.566 },
	{ name: '4号宿舍楼', address: '4号宿舍楼', latitude: 29.415, longitude: 106.567 },
	{ name: '教学楼A', address: '教学楼A', latitude: 29.411, longitude: 106.565 },
	{ name: '教学楼B', address: '教学楼B', latitude: 29.410, longitude: 106.564 },
	{ name: '学校食堂', address: '学校食堂', latitude: 29.413, longitude: 106.567 },
	{ name: '图书馆', address: '学校图书馆', latitude: 29.410, longitude: 106.566 },
]

// 创建标记
const createMarker = (lat, lng) => {
	return {
		id: 0,
		latitude: parseFloat(lat),
		longitude: parseFloat(lng)
	}
}

// 更新选中位置
const updateSelected = (lat, lng, name = '') => {
	const latNum = parseFloat(lat)
	const lngNum = parseFloat(lng)
	selectedAddress.value = {
		name: name || `位置(${latNum.toFixed(4)}, ${lngNum.toFixed(4)})`,
		latitude: latNum,
		longitude: lngNum
	}
	markers.value = [createMarker(latNum, lngNum)]
}

// 用户点击定位按钮
const onLocateClick = () => {
	locating.value = true
	uni.getLocation({
		type: 'gcj02',
		success: (res) => {
			mapLatitude.value = res.latitude
			mapLongitude.value = res.longitude
			updateSelected(res.latitude, res.longitude)
			locating.value = false
		},
		fail: () => {
			locating.value = false
			uni.showToast({ title: '定位失败，请手动选择位置', icon: 'none' })
		}
	})
}

// 点击地图选点
const onMapTap = (e) => {
	const lat = e.detail.latitude
	const lng = e.detail.longitude
	if (lat && lng) {
		mapLatitude.value = lat
		mapLongitude.value = lng
		updateSelected(lat, lng)
	}
}

// 选择常用地点
const selectQuickLocation = (item) => {
	mapLatitude.value = item.latitude
	mapLongitude.value = item.longitude
	selectedAddress.value = {
		name: item.name,
		address: item.address,
		latitude: item.latitude,
		longitude: item.longitude
	}
	markers.value = [createMarker(item.latitude, item.longitude)]
}

// 确认地址并返回上一页
const confirmAddress = () => {
	if (!selectedAddress.value) {
		uni.showToast({ title: '请先选择地址', icon: 'none' })
		return
	}
	const pages = getCurrentPages()
	const prevPage = pages[pages.length - 2]
	if (addressType.value === 'pickup') {
		prevPage.$vm.onPickupAddressSelected && prevPage.$vm.onPickupAddressSelected(selectedAddress.value)
	} else {
		prevPage.$vm.onAddressSelected && prevPage.$vm.onAddressSelected(selectedAddress.value)
	}
	uni.navigateBack()
}

// 手动输入搜索提示
const onManualSearch = () => {
	uni.showToast({ title: '请在地图上点击选择位置', icon: 'none', duration: 1500 })
}

onLoad((options) => {
	if (options.type === 'pickup') {
		addressType.value = 'pickup'
		navTitle.value = '选择取件地址'
	} else {
		addressType.value = 'destination'
		navTitle.value = '选择收件地址'
	}

	const sysInfo = uni.getSystemInfoSync()
	navBarHeight.value = sysInfo.statusBarHeight || 0

	// 如果从其他页面传入了坐标，直接使用
	if (options.lat && options.lng) {
		mapLatitude.value = parseFloat(options.lat)
		mapLongitude.value = parseFloat(options.lng)
	}

	// 初始化：默认显示学校位置
	updateSelected(mapLatitude.value, mapLongitude.value)
})
</script>

<style scoped>
.container {
	height: 100vh;
	display: flex;
	flex-direction: column;
	background-color: #f5f7fa;
	position: relative;
}

.nav-bar {
	position: fixed;
	top: 0;
	left: 0;
	right: 0;
	background: #fff;
	z-index: 1000;
}

.nav-content {
	height: 44px;
	display: flex;
	align-items: center;
	justify-content: center;
}

.nav-title {
	font-size: 32rpx;
	font-weight: bold;
	color: #333;
}

.search-bar {
	position: fixed;
	left: 0;
	right: 0;
	display: flex;
	align-items: center;
	padding: 16rpx 30rpx;
	background-color: #fff;
	z-index: 999;
	box-shadow: 0 2rpx 10rpx rgba(0, 0, 0, 0.05);
}

.search-input {
	flex: 1;
	height: 72rpx;
	background: #f5f7fa;
	border-radius: 36rpx;
	padding: 0 30rpx;
	font-size: 28rpx;
}

.placeholder {
	color: #c0c4cc;
}

.search-btn {
	margin-left: 20rpx;
	background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
	color: #fff;
	border-radius: 36rpx;
	padding: 0 36rpx;
	height: 64rpx;
	line-height: 64rpx;
	font-size: 26rpx;
	font-weight: bold;
}

.map-view {
	width: 100%;
	flex: 1;
	margin-top: 136rpx;
}

.locate-btn {
	position: fixed;
	right: 30rpx;
	bottom: 380rpx;
	width: 88rpx;
	height: 88rpx;
	background: #fff;
	border-radius: 50%;
	display: flex;
	align-items: center;
	justify-content: center;
	box-shadow: 0 4rpx 20rpx rgba(0, 0, 0, 0.12);
	z-index: 997;
}

.locate-icon {
	font-size: 40rpx;
	color: #667eea;
}

.quick-locations {
	position: fixed;
	left: 0;
	right: 0;
	bottom: 120rpx;
	background: #fff;
	padding: 20rpx 30rpx;
	box-shadow: 0 -4rpx 20rpx rgba(0, 0, 0, 0.05);
	z-index: 997;
}

.quick-title {
	font-size: 24rpx;
	color: #999;
	display: block;
	margin-bottom: 16rpx;
}

.quick-scroll {
	white-space: nowrap;
}

.quick-list {
	display: inline-flex;
	gap: 16rpx;
	padding-bottom: 4rpx;
}

.quick-item {
	background: #f0f2ff;
	color: #667eea;
	font-size: 24rpx;
	padding: 10rpx 24rpx;
	border-radius: 24rpx;
	white-space: nowrap;
	flex-shrink: 0;
}

.bottom-bar {
	position: fixed;
	bottom: 0;
	left: 0;
	right: 0;
	display: flex;
	align-items: center;
	justify-content: space-between;
	padding: 20rpx 30rpx;
	background: #fff;
	box-shadow: 0 -4rpx 20rpx rgba(0, 0, 0, 0.05);
	padding-bottom: calc(20rpx + env(safe-area-inset-bottom));
	z-index: 998;
}

.selected-info {
	flex: 1;
	margin-right: 20rpx;
}

.selected-name {
	display: block;
	font-size: 28rpx;
	font-weight: bold;
	color: #333;
	margin-bottom: 4rpx;
}

.selected-addr {
	font-size: 22rpx;
	color: #999;
}

.selected-tip {
	font-size: 24rpx;
	color: #999;
}

.confirm-btn {
	background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
	color: #fff;
	border-radius: 40rpx;
	padding: 0 40rpx;
	height: 72rpx;
	line-height: 72rpx;
	font-size: 28rpx;
	font-weight: bold;
}

.confirm-btn[disabled] {
	background: #ddd;
	color: #999;
}
</style>
